    getLockUnlock: function (lock) {

        var sels = this.getSelectionModel().getSelections();
        var pks = []
        Ext.each(sels, function (record) { pks.push(record.get('pk')); });

        Ext.Msg.show({
            scope: this,
            title: 'PERGUNTA',
            icon: Ext.Msg.QUESTION,
            buttons: Ext.Msg.OKCANCEL,
            msg: 'Confirmar Ação ?',
            fn: function (button) {
                if (button == 'ok') {
                    var params = {
                        actionCustom: 'block_periods',
                        group_period: pks,
                        lock: lock
                    };

                    this._process(params);
                }
            },
        });
    },

