    createOrUpdateAcquisitionPeriod: function (option) {
        selected = this.getSelectionModel().getSelected()
        if (selected) {
            if (option == 1) {
                var message = 'Deseja criar os períodos aquisitivos? <br>Obs: Os usufrutos serão criados caso a data de usufruto fim e inicio estejam preenchidas.'
                var create_or_update = 'create'
            }
            else if (option == 2) {
                var message = 'Deseja atualizar os períodos aquisitivos? <br>Obs: Os períodos aquisitivos serão atualizados com as configurações atuais.'
                var create_or_update = 'update'
            }
            else {
                Ext.Msg.show({
                    title: 'Periodos Aquisitivos',
                    msg: 'Selecione a opção de criar ou atualizar no menu Período Aquisitivo',
                    icon: Ext.Msg.INFO,
                    buttons: Ext.Msg.OK
                });
                return
            }

            Ext.Msg.show({
                scope: this,
                title: 'PERGUNTA',
                icon: Ext.Msg.QUESTION,
                buttons: Ext.Msg.OKCANCEL,
                msg: message,
                fn: function (button) {
                    if (button == 'ok') {
                        var params = {
                            actionCustom: 'generate_all_acquisition_periods',
                            group_period: this.getSelectionModel().getSelected().id,
                            create_or_update: create_or_update
                        };

                        this._process(params);
                    }
                },
            });


        } else {
            Ext.Msg.show({
                title: 'Criar Periodos Aquisitivos',
                msg: 'Selecione um grupo',
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK
            });
        }
    },

