    _process: function (params, window_, externalCallback) {
        var rest = Ext._create('rh.dayoff.groupperiod.Restful', {});
        var mask = Ext._create('Ext.LoadMask', this.getEl(), { msg: 'Processando informações.' });
        var wnd = window_ == null ? this : window_;
        externalCallback = wnd.externalCallback || externalCallback;

        mask.show();
        rest._process(
            params,
            {
                scope: this,
                fn: function (rst) {
                    core.invokeCallback((externalCallback || { fn: Ext.emptyFn }), rst.message);
                }
            },
            {
                fn: function (message) {
                    Ext.Msg.show({
                        title: 'Informando',
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK,
                        msg: message
                    });
                }
            },
            {
                fn: function () {
                    mask.hide();
                }
            }
        );
    },

